'use strict';
const topics=[
{title:'How often?',zh:'活動頻率',pages:'59–60',subtitle:'一次、兩次、每個星期……用英文說說你的日常！',words:[['once','一次'],['twice','兩次'],['three times','三次'],['week','星期；週'],['month','月'],['year','年'],['play the piano','彈鋼琴'],['play cards','玩紙牌'],['go to the movies','去看電影'],['go abroad','出國']],sentences:[['How often do you play the piano?','你多久彈一次鋼琴？'],['I play the piano twice a week.','我每週彈兩次鋼琴。'],['How often does he go abroad?','他多久出國一次？'],['He goes abroad once a year.','他每年出國一次。'],['Do they play cards once a week?','他們每週玩一次紙牌嗎？'],["No, she doesn't.",'不，她沒有。']],grammar:[['How often ___ he go abroad?','does',['do','is','are'],'he 是第三人稱單數，問句用 does，後面的 go 用原形。'],['He ___ abroad once a year.','goes',['go','going','do'],'肯定句主詞是 he，go 要加 es 成為 goes。'],['我每週彈兩次鋼琴。','I play the piano twice a week.',['I play the piano once a week.','I play the piano twice a year.','I play cards twice a week.'],'twice a week 就是「每週兩次」。'],['Do they play cards?（肯定回答）','Yes, they do.',["Yes, they does.",'Yes, she does.','Yes, they are.'],'Do they 開頭的問句，用 Yes, they do. 回答。']],tips:'<p><b>How often do you + 原形動詞?</b><br>詢問「你多久做一次……？」</p><p><b>once / twice / three times a week</b><br>每週一次／兩次／三次；week 也能換成 month 或 year。</p><p><b>How often does he go abroad?<br>He goes abroad once a year.</b><br>does 後用 go；肯定句 he 後用 goes。</p>'},
{title:'Shopping time!',zh:'衣物與購物',pages:'67–68',subtitle:'準備好購物清單，挑對單字，也說對數量。',words:[['jeans','牛仔褲'],['pants','長褲'],['shorts','短褲'],['socks','襪子'],['glasses','眼鏡'],['gloves','手套'],['earrings','耳環'],['shoes','鞋子'],['boots','靴子'],['a pair of pants','一條長褲'],['a bag of chips','一包洋芋片'],['a bottle of water','一瓶水'],['a can of soda','一罐汽水'],['a piece of cake','一塊蛋糕'],['a box of cookies','一盒餅乾'],['a slice of bread','一片麵包'],['a cup of tea','一杯茶'],['a glass of juice','一杯果汁']],sentences:[['What do you want to buy?','你想買什麼？'],['I want to buy a pair of boots.','我想買一雙靴子。'],['What does she want to buy?','她想買什麼？'],['She wants to buy two cans of soda.','她想買兩罐汽水。'],['Do you want to buy a pair of shoes?','你想買一雙鞋子嗎？'],['He wants to buy a bag of chips.','他想買一包洋芋片。']],grammar:[['She ___ to buy a pair of glasses.','wants',['want','wanting','do'],'主詞 she 是第三人稱單數，肯定句用 wants。'],['What does he ___ to buy?','want',['wants','wanting','does'],'does 後接原形動詞 want。'],['兩罐汽水是……','two cans of soda',['two can of soda','two pair of soda','two cups of tea'],'兩罐要用複數 cans；soda 不需要加 s。'],['I want to buy a ___ of shoes.','pair',['bottle','slice','cup'],'鞋子通常成雙，使用 a pair of shoes。']],tips:'<p><b>What do you want to buy?</b><br>你想買什麼？ I want to buy…</p><p><b>What does she want to buy?<br>She wants to buy a pair of glasses.</b><br>does 後用 want；肯定句 she 後用 wants。</p><p><b>a pair of shoes / two bags of chips</b><br>一雙鞋子／兩包洋芋片。數量超過一時，量詞要改成複數。</p>'},
{title:'Name that price!',zh:'數字與價格',pages:'75–76',subtitle:'看懂數字和標價，成為英文購物小達人。',words:[['sixty','六十'],['seventy','七十'],['eighty','八十'],['ninety','九十'],['one hundred','一百'],['one thousand','一千'],['cheap','便宜的'],['expensive','昂貴的'],['ring','戒指'],['belt','皮帶'],['backpack','背包'],['two hundred dollars','兩百元'],['one hundred and fifty dollars','一百五十元'],['six hundred and ninety dollars','六百九十元']],sentences:[['How much is the belt?','這條皮帶多少錢？'],["It's two hundred dollars.",'它是兩百元。'],['How much are the gloves?','這雙手套多少錢？'],["They're one hundred and fifty dollars.",'它們是一百五十元。'],['How much is the pair of jeans?','這條牛仔褲多少錢？'],['The skirts are three thousand dollars.','這些裙子是三千元。']],grammar:[['How much ___ the backpack?','is',['are','do','does'],'backpack 是單數，問價格用 How much is…?'],['How much ___ the gloves?','are',['is','do','does'],'gloves 是複數，問價格用 How much are…?'],['How much is the pair of jeans?','It’s one thousand dollars.',['They’re one thousand dollars.','It’s one thousands dollars.','It’s one thousand dollar.'],'主詞是單數 pair，所以用 It’s；明確數字後 hundred / thousand 不加 s。'],['皮帶標價 $690，應該說……','six hundred and ninety dollars',['six hundred and nineteen dollars','sixty-nine dollars','six thousand and ninety dollars'],'690 = six hundred and ninety；ninety 是 90，nineteen 是 19。']],tips:'<p><b>How much is the belt?<br>It’s two hundred dollars.</b><br>單數物品用 is，回答用 It’s。</p><p><b>How much are the gloves?<br>They’re one hundred and fifty dollars.</b><br>複數物品用 are，回答用 They’re。</p><p><b>How much is the pair of jeans?</b><br>這裡的主詞是單數 pair，所以用 is。</p><p><b>two hundred / three thousand</b><br>明確數字後，hundred、thousand 不加 s。</p>'}];
const modes=[['quiz','單字挑戰'],['listen','聽力任務'],['order','句型拼排'],['learn','單字練習']];
let topic=0,mode='quiz',round=[],index=0,score=0,correct=0,locked=false,mistakes=[],selected=[],bank=[],flipped=false;
const $=id=>document.getElementById(id), shuffle=a=>a.map(x=>({x,r:Math.random()})).sort((a,b)=>a.r-b.r).map(o=>o.x);
const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function speak(text){const status=$('speech-status');status.textContent='';if(!('speechSynthesis'in window)){status.textContent='這個瀏覽器不支援語音，請改用單字挑戰或句型拼排。';return;}speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang='en-US';u.rate=.83;const voice=speechSynthesis.getVoices().find(v=>v.lang==='en-US')||speechSynthesis.getVoices().find(v=>v.lang.startsWith('en'));if(voice)u.voice=voice;u.onerror=e=>{if(!['interrupted','canceled'].includes(e.error))status.textContent='語音暫時無法播放，請重試或切換單字挑戰。';};speechSynthesis.speak(u);}
function chrome(){const t=topics[topic];$('topics').innerHTML=topics.map((t,i)=>`<button class="topic ${i===topic?'active':''}" data-topic="${i}" aria-pressed="${i===topic}"><span class="num">0${i+1}</span><span><strong>${t.zh}</strong><small>課本 p.${t.pages}</small></span></button>`).join('');$('modes').innerHTML=modes.map(([id,label])=>`<button class="mode ${id===mode?'active':''}" data-mode="${id}" aria-pressed="${id===mode}">${label}</button>`).join('');$('title').textContent=t.title;$('subtitle').textContent=t.subtitle;$('chapter').textContent=`MISSION 0${topic+1} · ${t.zh}`;$('tips').innerHTML=t.tips;$('score').textContent=`★ ${score} 分`;}
function start(t=topic,m=mode,retry=null){if('speechSynthesis'in window)speechSynthesis.cancel();topic=t;mode=m;index=0;score=0;correct=0;mistakes=[];const data=topics[t];round=retry|| (m==='order'?shuffle(data.sentences).map(([answer,zh])=>({answer,zh})):m==='learn'?data.words.map(([answer,zh])=>({answer,zh})):m==='listen'?shuffle(data.words).slice(0,10).map(([en,zh])=>({prompt:'聽一聽，選出正確的意思',audio:en,answer:zh,options:shuffle([zh,...shuffle(data.words.filter(w=>w[1]!==zh)).slice(0,3).map(w=>w[1])]),explanation:en+' = '+zh})):shuffle([...shuffle(data.words).slice(0,6).map(([en,zh])=>({prompt:zh,answer:en,options:shuffle([en,...shuffle(data.words.filter(w=>w[0]!==en)).slice(0,3).map(w=>w[0])]),explanation:en+' = '+zh})),...data.grammar.map(([prompt,answer,wrong,explanation])=>({prompt,answer,options:shuffle([answer,...wrong]),explanation}))]));$('speech-status').textContent='';chrome();render();}
function progress(){return `<div class="progressline"><span>${mode==='learn'?'單字卡':'本回合'} ${index+1} / ${round.length}</span><span>${mode==='learn'?'點卡片看中文':'每題 10 分 · 答完再前進'}</span></div><div class="progress" role="progressbar" aria-label="答題進度" aria-valuemin="0" aria-valuemax="${round.length}" aria-valuenow="${index}"><span style="width:${100*index/round.length}%"></span></div>`;}
function render(){locked=false;selected=[];flipped=false;const q=round[index];$('score').textContent=`★ ${score} 分`;if(mode==='learn'){$('game').innerHTML=progress()+`<button class="flash" id="flip"><span class="q-type">WORD EXPLORER</span><span class="word">${escapeHTML(q.answer)}</span><span class="translation" id="translation" hidden>${escapeHTML(q.zh)}</span><span class="hint">點一下，翻開中文意思</span></button><div class="actions"><button class="sound" id="say">▶ 聽發音</button><div><button class="secondary" id="prev" ${index===0?'disabled':''}>上一張</button> <button class="primary" id="next">${index===round.length-1?'回到第一張':'下一張'}</button></div></div>`;return;}
if(mode==='order'){bank=shuffle(q.answer.split(' ').map((word,id)=>({word,id})));$('game').innerHTML=progress()+`<div class="q-type">BUILD A SENTENCE</div><h3 class="prompt">${escapeHTML(q.zh)}</h3><p class="helper">依序點選字詞組成句子；點上方字詞可撤回。</p><div id="tray" class="answertray tokens" aria-label="你的句子"></div><div id="bank" class="tokens"></div><div id="feedback" aria-live="polite"></div><div class="actions"><button class="secondary" id="clear">清空重排</button><button class="primary" id="check" disabled>檢查答案</button></div>`;drawTokens();return;}
$('game').innerHTML=progress()+`<div class="q-type">${mode==='listen'?'LISTEN & CHOOSE':'CHOOSE YOUR ANSWER'}</div><h3 class="prompt">${escapeHTML(q.prompt)}</h3>${mode==='listen'?'<div class="listen"><button class="sound" id="say">▶ 播放英文</button><p>可重複播放，慢慢聽就好。</p></div>':''}<div class="choices">${q.options.map((o,i)=>`<button class="choice" data-choice="${i}"><b>${'ABCD'[i]}</b><span>${escapeHTML(o)}</span></button>`).join('')}</div><div id="feedback" aria-live="polite"></div><div class="actions"><span class="helper">選一個答案，看看你學會了多少。</span><button class="primary" id="next" disabled>下一題 →</button></div>`;}
function drawTokens(){$('tray').innerHTML=selected.length?selected.map(id=>`<button class="token" data-remove="${id}" ${locked?'disabled':''}>${escapeHTML(bank.find(w=>w.id===id).word)}</button>`).join(''):'<span class="helper">你的英文句子會出現在這裡</span>';$('bank').innerHTML=bank.map(w=>`<button class="token" data-add="${w.id}" ${selected.includes(w.id)||locked?'disabled':''}>${escapeHTML(w.word)}</button>`).join('');if($('check'))$('check').disabled=selected.length!==bank.length;}
function grade(answer){if(locked)return;locked=true;const q=round[index],ok=answer===q.answer;if(ok){correct++;score+=10;}else mistakes.push(q);$('score').textContent=`★ ${score} 分`;if(mode==='order'){drawTokens();$('clear').disabled=true;$('check').outerHTML='<button class="primary" id="next">下一題 →</button>';}else document.querySelectorAll('[data-choice]').forEach(b=>{const value=q.options[Number(b.dataset.choice)];b.disabled=true;if(value===q.answer)b.classList.add('correct');else if(value===answer)b.classList.add('wrong');});$('feedback').innerHTML=`<div class="feedback ${ok?'good':'bad'}"><strong>${ok?'✓ 答對了！＋10 分':'再記住一次，下次就會了！'}</strong>${!ok?'正確答案：'+escapeHTML(q.answer)+'<br>':''}${escapeHTML(q.explanation||q.zh)}${mode==='order'?'<br><button class="sound" id="say">▶ 聽完整句子</button>':''}</div>`;$('next').disabled=false;$('next').textContent=index===round.length-1?'查看成果 ★':'下一題 →';}
function finish(){$('game').innerHTML=`<div class="result"><div class="q-type">MISSION COMPLETE</div><h3>${correct===round.length?'太棒了，全部答對！':'完成挑戰，繼續進步！'}</h3><div class="big">${score}<span style="font-size:22px"> / ${round.length*10}</span></div><p>答對 ${correct} / ${round.length} 題 · ${Math.round(correct/round.length*100)}% 正確率</p><div class="actions" style="justify-content:center">${mistakes.length?'<button class="primary" id="retry">再練錯題</button>':''}<button class="${mistakes.length?'secondary':'primary'}" id="restart">再玩一次</button><button class="secondary" id="newtopic">下一個主題 →</button></div>${mistakes.length?'<ul class="review">'+mistakes.map(q=>`<li>${escapeHTML(q.prompt||q.zh)}<b>${escapeHTML(q.answer)}</b>${escapeHTML(q.explanation||'')}</li>`).join('')+'</ul>':''}</div>`;}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;if(b.dataset.topic!==undefined){start(Number(b.dataset.topic));return;}if(b.dataset.mode){start(topic,b.dataset.mode);return;}if(b.dataset.choice!==undefined){grade(round[index].options[Number(b.dataset.choice)]);return;}if(b.dataset.add!==undefined&&!locked){selected.push(Number(b.dataset.add));drawTokens();return;}if(b.dataset.remove!==undefined&&!locked){selected=selected.filter(i=>i!==Number(b.dataset.remove));drawTokens();return;}switch(b.id){case'flip':flipped=!flipped;$('translation').hidden=!flipped;break;case'say':speak(round[index].audio||round[index].answer);break;case'prev':index--;render();break;case'next':if(mode==='learn'){index=(index+1)%round.length;render();}else if(locked){index++;if(index>=round.length)finish();else render();}break;case'check':grade(selected.map(id=>bank.find(w=>w.id===id).word).join(' '));break;case'clear':selected=[];drawTokens();break;case'retry':start(topic,mode,shuffle([...mistakes]));break;case'restart':start();break;case'newtopic':start((topic+1)%topics.length);break;}});
start();
if(document.modelContext?.registerTool){const controller=new AbortController();try{Promise.resolve(document.modelContext.registerTool({name:'start_english_practice',description:'Start a fresh English practice round for one textbook topic and mode, resetting the current round score.',inputSchema:{type:'object',properties:{topic:{type:'integer',minimum:0,maximum:2},mode:{type:'string',enum:['quiz','listen','order','learn']}},required:['topic','mode'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!input||!Number.isInteger(input.topic)||input.topic<0||input.topic>2||!modes.some(m=>m[0]===input.mode))throw new Error('Invalid topic or mode');start(input.topic,input.mode);return{topic:topics[topic].zh,mode,questions:round.length,score};}},{signal:controller.signal})).catch(()=>{});window.addEventListener('pagehide',()=>controller.abort(),{once:true});}catch{}}
